insert into public.board_exam_questions (board, contest_name, career_name, exam_year, exam_date, exam_type, item_number, subject, support_text, stem, options, official_answer, needs_visual, legal_review_required, state, career_category, source_url, answer_key_url, review_note) values
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',1,'Língua Portuguesa',null,'Observe o texto a seguir. À Beça Gumercindo Bessa (1859-1913), jornalista e jurista alagoano, foi adversário de Rui Barbosa na Questão Acreana, em que o Estado do Amazonas pretendia incorporar o Território do Acre. Bessa venceu a questão em favor do Acre, apresentando argumentos irrefutáveis e numa quantidade impressionante. Posteriormente, mas não muito, Rodrigues Alves (Presidente do Brasil de 1902 a 1906) diria a um cidadão que lhe apresentava um pedido com justificativas infindáveis: “O senhor tem argumentos à Bessa”. A partir daí, popularizou-se a expressão à beça com o sentido de uma grande quantidade ou intensidade. Por que os dois esses viraram cê-cedilha? Ninguém sabe. (Reinaldo Pimenta, A Casa da Mãe Joana 2) A ideia central do texto é a de','{"A": "explicar a origem histórica de uma expressão popular.", "B": "justificar a duplicidade de grafia de uma expressão.", "C": "indicar o sentido preciso da expressão à beça.", "D": "mostrar como as palavras se constroem socialmente.", "E": "documentar um erro ortográfico."}'::jsonb,'A',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',2,'Língua Portuguesa',null,'Assinale a frase em que o segmento sublinhado foi substituído de forma conveniente por um particípio.','{"A": "Qualquer pessoa que não tem senso de humor está à mercê de todos / desprovida de.", "B": "Os empresários que não têm dinheiro, recorrem aos empréstimos bancários / encarecidos de.", "C": "Os empregados que não têm iniciativa não recebem promoções / inativos.", "D": "Os clientes que não têm possibilidades de locomoção, sobem pelas escadas rolantes / impossíveis.", "E": "Aquele que não tem motivo para pedir ajuda, deve ficar quieto / desmotivado."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',3,'Língua Portuguesa',null,'Assinale a frase em que a utilização do acento grave indicativo da crase é realizada de forma errada.','{"A": "Seis horas de sono, seis horas no estudo das leis, quatro passadas em oração, as restantes dedicadas à natureza.", "B": "As datas, só elas dão verdadeira consistência à vida e à sorte.", "C": "O futuro é algo que todos nós atingimos à velocidade de sessenta minutos por hora.", "D": "À medida que tenho menos tempo para praticar as coisas, menos curiosidade tenho por aprendê-las.", "E": "O futuro não pertence à ninguém. Não há precursores, apenas há atrasados."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',4,'Língua Portuguesa',null,'Em todas as frases abaixo aparece a conjunção e sublinhada. Assinale a frase em que ela é empregada com valor adversativo.','{"A": "Vida: um espaço de tempo cuja primeira metade é arruinada por nossos pais e a segunda metade, por nossos filhos.", "B": "Uma casa é feita de tijolo e pedra. Um lar é feito apenas de amor.", "C": "Esculpir: eu escolho um bloco de mármore e retiro tudo o que não preciso.", "D": "Arte é fazer alguma coisa do nada e vendê-la.", "E": "Nada tenho a dizer e estou dizendo-o. Tal é a poesia."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',5,'Língua Portuguesa',null,'A maioria das palavras mostra vários significados (polissemia), o que também ocorre com as preposições. Indique a frase em que a preposição PARA tem seu significado corretamente indicado.','{"A": "Meu sonho é ir para a Europa / finalidade.", "B": "Saiu para comprar roupas de frio / direção.", "C": "Estava para sair quando chegaram as visitas / proximidade.", "D": "O ônibus era para cinquenta passageiros / interesse.", "E": "Para os pássaros, o canto faz parte da vida / destinação."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',6,'Língua Portuguesa',null,'Observe o trecho seguinte: “A compra desses livros, mesmo que estejamos num país sem inflação exagerada, nos ensina a valorizar nosso dinheiro, só o empregando em necessidades reais.” A locução sublinhada poderia ser substituída, sem prejuízo do sentido, por','{"A": "visto que.", "B": "além do que.", "C": "desde que.", "D": "ainda que.", "E": "mais do que."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',7,'Língua Portuguesa',null,'Assinale a frase em que o vocábulo sublinhado pertence à classe dos adjetivos.','{"A": "Os velhos amigos estão sempre conosco.", "B": "Aconselhe seu amigo quando for necessário.", "C": "Devemos sempre homenagear um amigo.", "D": "Em nossa família, um é amigo do outro.", "E": "Nenhuma pessoa possui muitos amigos."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',8,'Língua Portuguesa',null,'Assinale a frase em que é optativo o emprego do artigo sublinhado.','{"A": "Engenheiros são as únicas pessoas que não podem ignorar a Matemática.", "B": "Uma coisa urgente a fazer é prender todos os corruptos.", "C": "Nunca diga mentiras para os seus pais.", "D": "O Brasil é o maior país da América do Sul.", "E": "É necessário acabar com a inflação neste país."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',10,'Língua Portuguesa',null,'Assinale a frase em que os termos sublinhados não mostram, em caso de troca de posição dos termos, mudança de significado.','{"A": "Marinheiro valente.", "B": "Bom homem.", "C": "Grande sujeito.", "D": "Pobre professor.", "E": "Simples funcionário."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',11,'Língua Portuguesa',null,'Os adjetivos podem indicar qualidades positivas ou negativas, características, estados ou relações dos substantivos. Assinale a frase em que o adjetivo destacado indica uma característica.','{"A": "Esse é um mundo pequeno, mas eu não queria ter que pintá- lo.", "B": "As pessoas, como os metais, têm apenas uma superfície brilhante.", "C": "A Terra é mais nobre que o mundo que colocamos sobre ela.", "D": "O mundo pode ser um palco, mas o elenco é um horror.", "E": "Para este mundo ficar bom, é preciso fazer outro."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',12,'Língua Portuguesa',null,'Em muitos adjetivos pátrios compostos, o primeiro termo mostra uma forma alatinada e reduzida. Assinale a opção em que o adjetivo citado corresponde corretamente aos países indicados.','{"A": "anglo-germânico (Irlanda e Alemanha).", "B": "austro-inglês (Austrália e Inglaterra).", "C": "euro-americano (Europa e América).", "D": "teuto-nipônico (Filipinas e Japão).", "E": "sino-hispânico (Japão e Espanha)"}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',13,'Língua Portuguesa',null,'Observe a seguinte frase: “Consta que o mundo muda constantemente e, na Natureza, ser constante seria uma inconstância”. Nessa frase foram sublinhadas quatro palavras da mesma família, mas de classes gramaticais diferentes. Assinale a opção em que foram indicadas, na mesma ordem de classes, quatro palavras da mesma família.','{"A": "estudar / estudantemente / estudado / estudo.", "B": "entreter / entretidamente / entretido / entretenimento.", "C": "convir / convenientemente / convencido / convenção.", "D": "prever / previamente / provisto / prevenção.", "E": "divertir / divertidamente / divertido / diversificação."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',14,'Língua Portuguesa',null,'Na frase “Ninguém ousa dizer adeus aos próprios hábitos. Muitos suicidas se detiveram no limiar da morte ao pensar no café onde vão jogar todas as noites sua partida de dominó” há um pronome possessivo sublinhado, cujo valor é o de','{"A": "indefinição.", "B": "designação de um hábito.", "C": "de deferência e respeito.", "D": "aproximação numérica.", "E": "propriedade material."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',15,'Língua Portuguesa',null,'Em todas as frases abaixo está sublinhado o advérbio “não” ou “nunca”; todas essas frases foram reescritas de forma a eliminar esses advérbios, mas conservando o sentido original. Assinale a frase em que essa modificação foi feita de forma inadequada.','{"A": "Não há nada de tão absurdo que o hábito não torne aceitável / Nada há de tão absurdo que o hábito não torne aceitável.", "B": "Não existe nada mais forte que o hábito / Nada é mais forte que o hábito.", "C": "As mudanças nunca ocorrem sem inconvenientes / As mudanças sempre ocorrem com inconvenientes.", "D": "A coragem é filha da prudência, não da temeridade / A coragem é filha da prudência, mas sim da temeridade.", "E": "E amanhã não seremos o que fomos nem o que somos / E amanhã seremos diferentes do que fomos e do que somos."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',16,'Língua Portuguesa',null,'As opções a seguir apresentam orações subordinadas adverbiais. Assinale aquela em que a classificação dada está correta.','{"A": "Se eu fosse rei, instituiria cátedras para ensinar a calar / oração comparativa.", "B": "Quando se tem tudo para temer, não se deve temer nada / oração condicional.", "C": "Não há nada de tão absurdo que o hábito não torne aceitável / oração consecutiva.", "D": "Algumas pessoas foram consideradas corajosas porque tinham medo de fugir / final.", "E": "Dai-me força e coragem para contemplar meu interior / concessiva."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',17,'Língua Portuguesa',null,'Assinale a frase em que o adjetivo sublinhado mostra uma função sintática diferente da que mostra nas demais frases.','{"A": "O hábito torna suportáveis até as coisas assustadoras.", "B": "O silêncio deles é uma eloquente afirmação.", "C": "O silêncio tornou-se sua linguagem materna.", "D": "Os bons homens são extremamente raros.", "E": "A sabedoria humana ensina muito se ensina a calar."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',18,'Língua Portuguesa',null,'Algumas vezes ocorrem duas palavras idênticas na grafia, mas diferentes na acentuação tônica como, por exemplo, crédito e credito (do verbo creditar). As palavras sublinhadas nas frases abaixo são idênticas graficamente a outras palavras, mas com acentuação tônica diferente e diferente significado. Assinale a frase cuja palavra sublinhada mostra outra acentuação, mas com o mesmo significado.','{"A": "O hábito é o grande guia da vida humana.", "B": "Ninguém ousa dizer adeus aos próprios hábitos. Muitos suicidas se detiveram no limiar da morte ao pensar no café onde vão jogar todas as noites sua partida de dominó.", "C": "Toda palavra pronunciada suscita seu sentido contrário.", "D": "É magnífico ouvir o silêncio daquele homem.", "E": "Os hieróglifos já são compreendidos pelos estudiosos."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',19,'Língua Portuguesa',null,'As preposições em língua portuguesa podem ser nocionais, quando colaboram semanticamente com a frase, e gramaticais, quando são exigidas pela regência de algum termo anterior. Assinale a frase em que a preposição sublinhada mostra valor gramatical.','{"A": "A verdadeira glória de um vencedor é a de ser clemente.", "B": "A frase é a toalete do espírito.", "C": "As mulheres não sabem o que dizer no fim de um amor.", "D": "O hábito é o grande guia da vida humana.", "E": "Os fatos devem provar a bondade das palavras."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',20,'Língua Portuguesa',null,'As opções a seguir apresentam um adjetivo sublinhado. Assinale aquela em que esse adjetivo foi substituído por uma oração adjetiva adequada.','{"A": "Ouso afirmar que são os homens, e não as mulheres, os culpados pela maioria dos casamentos infelizes / que denunciam a culpa do parceiro.", "B": "Temam menos a morte e mais a vida insuficiente / que não é bastante.", "C": "O hábito torna suportáveis até as coisas assustadoras / que levam susto.", "D": "O casamento, se queres saber a verdade, é um mal, mas um mal necessário / de que se prescinde.", "E": "Ser marido é um trabalho de tempo integral / que é diariamente íntegro. Informática"}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',21,'Informática',null,'Os monitores de vídeo podem ter diferentes resoluções de exibição. Assinale a resolução que corresponde, em pixels, à de vídeo 4K (UHD).','{"A": "1280 x 1080", "B": "1280 x 720", "C": "1920 x 1080", "D": "3840 x 2160", "E": "7680 x 4320"}'::jsonb,'D',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',22,'Informática',null,'Francisco estava utilizando o Explorador de Arquivos no Windows quando, inadvertidamente, excluiu um arquivo. Assinale a combinação de teclas que Francisco pode usar imediatamente para recuperar o arquivo.','{"A": "Ctrl+V", "B": "Alt+F4", "C": "Ctrl+C", "D": "Ctrl+X", "E": "Ctrl+Z"}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',23,'Informática',null,'João está editando um documento, no Word, composto por três segmentos: uma introdução de apresentação, um índice completo sobre os tópicos abordados e o corpo do documento. Em cada um desses segmentos, a numeração de páginas deve ser reiniciada a partir de 1. O recurso do MS Word que viabiliza e torna bem mais simples esse tipo de edição é','{"A": "a inserção de símbolos especiais.", "B": "o uso de cabeçalhos dinâmicos.", "C": "o uso de quebras de página.", "D": "o uso de quebras de seções.", "E": "o uso de rodapés dinâmicos."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',24,'Informática',null,'Analise as afirmativas a seguir, a respeito do uso de colunas no corpo de documentos criados no MS Word. I. O número de colunas não pode passar de 5. II. As colunas podem ser de larguras diferentes. III. Não é permitida a inserção de quebra de página no interior de uma coluna. Somente está correto o que se afirma em','{"A": "I.", "B": "II.", "C": "III.", "D": "I e II.", "E": "II e III."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',25,'Informática',null,'Maria recebeu um arquivo, intitulado “casa.jpg”, a ser incluído no texto do documento Word que ela está preparando. Assinale a opção da guia Inserir que Maria deve utilizar para fazer essa inserção.','{"A": "Formas.", "B": "Gráfico.", "C": "Imagens.", "D": "Instantâneo.", "E": "SmartArt. Legislação"}'::jsonb,'C',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',26,'Processo Legislativo',null,'Acerca da atuação dos órgãos da Assembleia Legislativa do Estado do Maranhão, à luz do texto de seu Regimento Interno, analise as seguintes atividades: I. Estabelecer diretrizes para divulgação das atividades da Assembleia. II. Interpretar e fazer observar o ordenamento jurídico de pessoal e dos serviços administrativos da Assembleia. III. Convidar o Deputado a retirar-se do recinto do Plenário, quando perturbar a ordem. IV. Receber, examinar e encaminhar aos órgãos competentes as reclamações ou representações de pessoas físicas ou jurídicas sobre violação ou qualquer forma de discriminação atentatória dos direitos e liberdades fundamentais. As referidas atividades, ainda que por meio das pessoas que os compõem, são de atribuição, respectivamente, dos seguintes órgãos:','{"A": "I – Secretaria; II – Corregedoria Parlamentar; III – Mesa; IV – Presidência.", "B": "I – Presidência; II – Mesa; III – Corregedoria Parlamentar; IV – Secretaria.", "C": "I – Presidência; II – Secretaria; III – Ouvidoria Parlamentar; IV – Mesa.", "D": "I – Mesa; II – Secretaria; III – Presidência; IV – Ouvidoria Parlamentar.", "E": "I – Secretaria; II – Mesa; III – Corregedoria Parlamentar; IV – Ouvidoria Parlamentar."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',27,'Processo Legislativo',null,'O procedimento de votação é aquele por meio do qual os Deputados estaduais deliberam sobre projetos de lei e de resolução, bem como as demais proposições de competência da Casa Legislativa. Sobre a votação na Assembleia Legislativa do Estado do Maranhão, de acordo com seu Regimento Interno, assinale a afirmativa correta.','{"A": "Quando, no curso de uma votação, se esgotar o tempo próprio da sessão, a votação ficará automaticamente prorrogada para a próxima sessão seguinte.", "B": "Em regra, as proposições serão votadas individualmente, podendo, por deliberação específica, excepcionalmente serem votadas em globo.", "C": "Em regra, dependerá de aprovação do Plenário o requerimento de destaque apresentado por bancada de Partido ou Bloco.", "D": "Pelo processo simbólico de votação, o Presidente, ao anunciar a votação de qualquer matéria, convidará os Deputados a favor para ficarem de pé, e proclamará o resultado manifesto dos votos, anunciando sempre os nomes dos Deputados que votaram contra.", "E": "A matéria não poderá ser colocada em votação se o Deputado autor da proposição estiver ausente de Plenário, salvo após sua inclusão na Ordem do Dia por duas sessões ordinárias consecutivas."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',28,'Processo Legislativo',null,'Um Secretário Estadual foi convocado a ser ouvido pela Assembleia Legislativa do Estado do Maranhão (ALEMA). No dia e hora em que comparecer perante a ALEMA, nos termos do Regimento Interno, a sessão para sua oitiva deverá ser uma sessão','{"A": "especial.", "B": "extraordinária.", "C": "ordinária.", "D": "solene.", "E": "preparatória."}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',29,'Processo Legislativo',null,'Quando finda uma legislatura, a regra geral é a de que serão arquivadas todas as proposições. Porém, o Regimento Interno da Assembleia Legislativa do Estado do Maranhão prevê algumas exceções a essa regra. Assinale a opção que configura uma exceção à regra geral de arquivamento ao fim da legislatura.','{"A": "Projeto de lei complementar.", "B": "Projeto de decreto legislativo.", "C": "Projeto de lei enviado pelo Poder Judiciário.", "D": "Projeto de resolução.", "E": "Moção de aplauso."}'::jsonb,'C',true,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',30,'Processo Legislativo',null,'José, servidor público da Assembleia Legislativa do Estado do Maranhão, teve a sua demissão, aplicada após processo administrativo disciplinar, invalidada por decisão judicial. Nesse caso, de acordo com o Estatuto dos Servidores Públicos Civis do Estado do Maranhão, é correto dizer que se aplicará a José o instituto jurídico de','{"A": "reversão.", "B": "reintegração.", "C": "readaptação.", "D": "recondução.", "E": "aproveitamento. Conhecimentos Específicos"}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',31,'Administração Geral',null,'Considere que determinada Secretaria do Estado X publicou edital de concurso público para a contratação de novos servidores públicos. No entanto, após mudança específica na legislação, aprovada pela Assembleia Legislativa, que reduziu drasticamente a demanda por funcionários, a Secretaria verificou que o prosseguimento do concurso, cujas provas ainda não tinham sido sequer aplicadas, se tornou desnecessário. Nesse caso, é correto afirmar que a Secretaria','{"A": "pode revogar o edital, em conformidade com o princípio da autotutela.", "B": "deve manter o concurso, visto que o princípio da sindicabilidade impede que ele seja cancelado.", "C": "pode anular o concurso, visto que o princípio da conveniência foi violado.", "D": "deve modificar os dispositivos conflitantes do edital, conforme prescreve o princípio da indisponibilidade do interesse privado.", "E": "pode convalidar o concurso, constituindo exceção ao princípio da intranscendência subjetiva das ações."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',32,'Administração Geral',null,'Devido a sua importância para a Administração Pública, alguns princípios foram expressamente previstos na Constituição Federal de 1988. Acerca dos princípios expressos para a Administração Pública, analise as assertivas a seguir. I. O princípio da legalidade permite que a Administração Pública pratique apenas atos que não sejam vedados, taxativamente, por lei em sentido formal. II. O princípio da eficiência preceitua que as atribuições dos agentes públicos sejam realizadas com presteza e rendimento profissional. III. O princípio da moralidade impede que um agente público nomeie seu cônjuge para cargo comissionado no órgão em que trabalha. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "I e II, apenas.", "D": "II e III, apenas.", "E": "I, II e III."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',33,'Administração Geral',null,'A divisão dos serviços e das competências da Administração Pública nas Secretarias da Cultura, da Comunicação Social, da Fazenda, entre outras, como ocorre no Governo do Maranhão, é chamada de','{"A": "descentralização por outorga.", "B": "concessão geográfica.", "C": "permissão unilateral.", "D": "delegação por colaboração.", "E": "desconcentração administrativa."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',34,'Administração Geral',null,'Assinale a opção que apresenta o tipo de estrutura organizacional que, embora ofereça riscos de conflito em função da dupla subordinação, busca aproveitar as principais vantagens das estruturas funcional e divisional.','{"A": "Estrutura Territorial.", "B": "Estrutura Linear.", "C": "Estrutura Simples.", "D": "Estrutura Matricial.", "E": "Estrutura Mecanicista."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',35,'Administração Geral',null,'Com relação à Administração Pública e suas divisões doutrinárias, assinale a opção que apresenta um exemplo de Administração Indireta no Estado do Maranhão.','{"A": "Polícia Civil do Maranhão (PC-MA).", "B": "Universidade Estadual do Maranhão (UEMA).", "C": "Assembleia Legislativa do Maranhão (ALEMA).", "D": "Corpo de Bombeiros Militar do Maranhão (CBM-MA).", "E": "Procuradoria-Geral do Estado do Maranhão (PGE-MA)."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',36,'Administração Geral',null,'A Autarquia representa um serviço autônomo, criado por lei, com o intuito de executar atividades típicas da Administração Pública. Esse tipo de entidade, que goza de uma série de prerrogativas, possui grande importância na configuração do Estado Brasileiro, estando presente tanto em nível federal quanto estadual e municipal. Uma característica elementar das Autarquias reside no fato de que elas','{"A": "não se submetem ao controle hierárquico dos órgãos ministeriais.", "B": "são regidas predominantemente por regras de direito privado.", "C": "constituem entidades despersonalizadas juridicamente.", "D": "adquirem atribuições em decorrência do processo de publicização do setor público não-estatal.", "E": "não necessitam realizar concursos públicos para a contratação de pessoal."}'::jsonb,'A',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',37,'Administração Geral',null,'As opções a seguir apresentam princípios do conceito de empreendedorismo governamental, desenvolvido na obra “Reinventando o Governo”, à exceção de uma. Assinale-a.','{"A": "Governo competitivo.", "B": "Governo orientado por missões.", "C": "Governo preventivo.", "D": "Governo orientado para o mercado.", "E": "Governo centralizado."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',38,'Administração Geral',null,'O conjunto de ideias sobre modelos de administração pública que traz à luz o conceito de paradigma do cliente, no qual os cidadãos devem ter suas necessidades satisfeitas pelos serviços ofertados pela Administração Pública é conhecido como','{"A": "nova gestão pública.", "B": "patrimonialismo de desempenho.", "C": "absolutismo.", "D": "parlamentarismo.", "E": "corporativismo."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',39,'Administração Geral',null,'Considere que uma fábrica de pregos e parafusos, localizada na cidade de Imperatriz (MA), utilize o seguinte processo na produção: após a fabricação das peças, elas são examinadas individualmente e, caso sejam identificadas não-conformidades, a peça é descartada. Esse processo de qualidade utilizado pela fábrica se baseia em métodos da era','{"A": "da garantia de qualidade.", "B": "do controle de qualidade.", "C": "da inspeção de qualidade.", "D": "da gestão de qualidade total.", "E": "do monitoramento estatístico da qualidade."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',40,'Administração Geral',null,'William E. Deming, uma das principais referências no campo da qualidade, ficou conhecido por sua experiência bem-sucedida no Japão pós-guerra, revolucionando a indústria desse país. Com base nessa experiência, Deming elaborou alguns princípios, conhecidos como “14 pontos de Deming”, que deveriam ser usados como diretrizes para a implementação de qualidade, tendo, como orientação','{"A": "o aumento da independência entre os departamentos.", "B": "a priorização dos negócios com base no preço.", "C": "a eliminação de slogans para a força de trabalho.", "D": "o fortalecimento do medo de erros e falhas.", "E": "a ênfase nos lucros extraordinários de curto prazo."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',41,'Administração Geral',null,'Em uma situação hipotética, o Governador do Estado Y, buscando embasamento para a elaboração de novas políticas públicas, solicitou a seus assessores que realizassem um estudo sobre a possível relação entre a melhoria da educação e a redução da violência no estado. Acerca do proposto pelo Governador, assinale a opção que apresenta uma ferramenta de qualidade adequada para esse estudo.','{"A": "Matriz GUT.", "B": "Diagrama de dispersão.", "C": "Folha de verificação.", "D": "5S.", "E": "6 Sigma."}'::jsonb,'B',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',42,'Administração Geral',null,'A gestão por resultados começou a ser implementada no Brasil após o Plano Diretor de Reforma do Aparelho do Estado (PDRAE), instituído no ano de 1995, em um momento de intensos debates acerca da reformulação do papel do Estado no contexto de globalização. Diante do exposto, acerca da gestão por resultados, é correto afirmar que','{"A": "retoma modelos participativos utilizados no modelo weberiano, como conselhos de políticas públicas e audiências públicas.", "B": "baseia-se na intensificação dos mecanismos de controle, fortalecendo regras autorreferentes.", "C": "exige a previsibilidade de funcionamento, reduzindo a autonomia dos gestores públicos.", "D": "delineia os objetivos com maior precisão, otimizando o exercício da accountability.", "E": "estimula a criação de símbolos de autoridade, encorajando o respeito hierárquico ao superior."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',43,'Administração Geral',null,'Os dados, obtidos pelo administrador, decorrentes da classificação dos materiais permitem que se dê atenção prioritária a determinados materiais da organização. Nesse sentido, destaca-se a importância do sistema de classificação utilizado, que, segundo a literatura, deve ter atributos como','{"A": "a praticidade, abordando um vasto número de características dos materiais para evitar duplicidades.", "B": "a flexibilidade, permitindo interfaces entre os diversos tipos de classificação e proporcionando uma visão global do material.", "C": "a abrangência, exigindo julgamentos simples e diretos do classificador, sem o emprego de conceitos abstratos.", "D": "a oportunidade, garantindo que as classificações permitam a distinção dos itens mesmo com análises intempestivas.", "E": "a materialidade, preceituando o uso de informações de fontes confiáveis, para possibilitar o consenso entre diferentes examinadores."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',44,'Direito Administrativo',null,'Em 2021 foi aprovada a Nova Lei de Licitações e Contratos (Lei nº 14.133/2021) para disciplinar, entre outras questões, as compras realizadas pela Administração Pública. Acerca dessa Nova Lei de Licitações e Contratos, é correto afirmar que','{"A": "é aplicável a toda a Administração Pública, sem exceções.", "B": "revogou imediatamente a Lei nº 8.666/1993, responsável por reger as compras públicas até então.", "C": "excluiu a possibilidade de pregão como modalidade de compra.", "D": "permite a continuidade do uso da Lei nº 8.666/1993 nos contratos em vigor celebrados sob a égide da antiga Lei de Licitações.", "E": "pode ser utilizada em combinação com os dispositivos da Lei nº 8.666/1993, possibilitando maior celeridade."}'::jsonb,'D',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',45,'Administração Geral',null,'A curva ABC é um método amplamente utilizado na gestão de materiais, tendo, como um de seus resultados a identificação','{"A": "dos itens de estoque da categoria A, que representam os itens mais importantes para a organização.", "B": "dos itens de estoque de categoria B, que podem ser usados como substitutos, em caso de falta de itens necessários.", "C": "dos itens de estoque da categoria C, que possuem máxima criticidade operacional.", "D": "de itens de estoque da categoria A, que representam os materiais de menor valor.", "E": "de itens de estoque da categoria B, que fazem parte dos imobilizados pertencentes à organização."}'::jsonb,'A',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',46,'Administração Geral',null,'Em uma empresa pública responsável por realizar a administração portuária, o estoque de determinada peça de manutenção é consumido na razão de 1.000 unidades por mês, sendo o seu tempo de reposição de 2 meses. Considerando que o estoque mínimo exigido para essa peça equivale a 1 mês de consumo, o ponto do pedido (ressuprimento) será de','{"A": "nenhuma unidade.", "B": "1000 unidades.", "C": "2000 unidades.", "D": "3000 unidades.", "E": "4000 unidades."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',47,'Administração Geral',null,'Com relação às possíveis estratégias de compra utilizadas por uma organização, analise as assertivas a seguir. I. A verticalização tem, como desvantagem, custos estruturais significativos. II. Enquanto a descentralização se sobressai em mercados de baixa previsibilidade, a centralização permite que a organização tenha ganhos de escala. III. A independência em relação ao mercado, de forma geral, é um dos diferenciais da horizontalização, característica que permite maior grau de customização produtiva. Está correto o que se afirma em','{"A": "I, apenas.", "B": "II, apenas.", "C": "I e II, apenas.", "D": "II e III, apenas.", "E": "I, II e III."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',48,'Administração Geral',null,'Em função dos novos contextos da sociedade, a gestão de materiais tem se adaptado e buscado novas soluções para fazer frente aos problemas considerados mais urgentes a serem enfrentados. Nesse sentido,','{"A": "a paletização, embora gere atrasos por ineficiente aproveitamento do espaço, previne as perdas e desperdícios por mau acondicionamento.", "B": "o Kanban permite a eliminação da necessidade de estoques, por meio do emprego do sistema de produção empurrada.", "C": "a metodologia ágil redesenha radicalmente os processos, priorizando conceitos de acessibilidade, minimizando o uso de sistemas de informação.", "D": "o Supply Chain Management reduz a necessidade de mão-de- obra, aproveitando-se de sistemas de parceria e terceirização, reduzindo os custos sociais.", "E": "a logística reversa possibilita coletar ou recuperar os resíduos do produto após seu consumo, reforçando o desenvolvimento sustentável."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',49,'Administração Geral',null,'Uma empresa maranhense de turbinas de geração eólica vendeu 100 turbinas em 2021 e 130 em 2022. Caso ela utilize a projeção como modelo de previsão de demanda de materiais, deve esperar vender, em 2023,','{"A": "100 turbinas.", "B": "115 turbinas.", "C": "130 turbinas.", "D": "160 turbinas.", "E": "169 turbinas."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',50,'Administração Geral',null,'No caso de uma empresa operar em um mercado consumidor de alta sazonalidade, a exemplo do mercado de chocolates, que atinge picos de venda em datas festivas, é adequado o uso do estoque','{"A": "em trânsito.", "B": "de antecipação.", "C": "de desacoplamento.", "D": "ponderado.", "E": "por just-in-time."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',51,'Arquivologia',null,'O que determina a idade dos documentos (corrente, intermediária e permanente) é','{"A": "o valor legal.", "B": "o valor probatório.", "C": "a frequência de uso.", "D": "a existência de código de classificação.", "E": "a existência de instrumento de pesquisa."}'::jsonb,'C',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',52,'Arquivologia',null,'Uma atividade que deve ser realizada no Arquivo Corrente é','{"A": "o arranjo.", "B": "a avaliação.", "C": "a descrição.", "D": "a elaboração de instrumentos de pesquisa.", "E": "a ordenação dos documentos em fundos."}'::jsonb,'B',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',53,'Arquivologia',null,'O objetivo do protocolo é','{"A": "analisar o perfil dos usuários do arquivo.", "B": "avaliar e selecionar os documentos.", "C": "reduzir a massa documental ao essencial.", "D": "determinar o valor dos documentos.", "E": "controlar os documentos que tramitam no órgão."}'::jsonb,'E',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',54,'Arquivologia',null,'A eliminação mecânica de todas as sujidades que se encontram nos documentos e nos agentes considerados agressores, tais como os clipes e grampos, oxidados ou não, os elementos utilizados como marcadores de folhas, as poeiras e demais elementos artificiais à estrutura física do documento, é denominada','{"A": "alisamento.", "B": "desinfestação.", "C": "fumigação.", "D": "higienização.", "E": "restauração."}'::jsonb,'D',false,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',55,'Arquivologia',null,'São exemplos de métodos de arquivamento por assunto:','{"A": "duplex, decimal e enciclopédico.", "B": "alfabético, geográfico e numérico simples.", "C": "numérico cronológico, decimal e unitermo.", "D": "dígito-terminal, duplex e unitermo.", "E": "geográfico, dicionário e decimal."}'::jsonb,'A',true,false,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',56,'Redação Oficial',null,'Na correspondência oficial, é muito comum a presença de pronomes de tratamento em forma abreviada. Assinale a forma de abreviação corretamente indicada.','{"A": "Vossa Excelência: V. Excia.", "B": "Vossas Excelências: VV. Excias.", "C": "Vossa Santidade: V. Se.", "D": "Vossas Majestades: VV. MM.", "E": "Vossa Alteza: V. Alt."}'::jsonb,'X',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','questão ANULADA pela banca; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',57,'Redação Oficial',null,'Em relação aos pronomes de tratamento, assinale a construção inadequada.','{"A": "Sua Excelência deseja fazer agora o discurso?", "B": "Sua Excelência, Senhor Ministro, está passando bem?", "C": "Vossa Excelência deseja rever o projeto?", "D": "Vossas Excelências, Srs. Ministros, querem declarar algo?", "E": "Vossa Majestade quer subscrever o manifesto?"}'::jsonb,'A',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',58,'Redação Oficial',null,'O emprego correto dos sinais de pontuação é uma necessidade da escritura oficial. Assinale a frase que mostra pontuação adequada.','{"A": "Uma pequena obra da qual ninguém poderá dizer sem injustiça que não tem pé nem cabeça: nela, ao contrário, tudo é, ao mesmo tempo, cabeça e pé.", "B": "Uma pequena obra da qual ninguém poderá dizer, sem injustiça, que não tem pé nem cabeça: nela, ao contrário, tudo é, ao mesmo tempo, cabeça e pé.", "C": "Uma pequena obra da qual ninguém poderá dizer, sem injustiça, que não tem pé, nem cabeça: nela, ao contrário, tudo é, ao mesmo tempo, cabeça e pé.", "D": "Uma pequena obra da qual ninguém poderá dizer, sem injustiça, que não tem pé nem cabeça: nela ao contrário tudo é, ao mesmo tempo, cabeça e pé.", "E": "Uma pequena obra da qual ninguém poderá dizer sem injustiça, que não tem pé nem cabeça: nela, ao contrário, tudo é, ao mesmo tempo, cabeça e pé."}'::jsonb,'B',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',59,'Redação Oficial',null,'A Redação Oficial é, obrigatoriamente, impessoal e objetiva. Assinale a frase que segue esses parâmetros.','{"A": "A Constituição foi construída de modo apressado e, por isso, necessita de tantas interferências.", "B": "Maravilhosa essa ideia de arquivarmos toda a correspondência na forma digital.", "C": "Acredito que será altamente benéfica a viagem do Presidente ao Oriente.", "D": "Sem dúvida, a inflação brasileira sofrerá forte queda no segundo semestre.", "E": "A comitiva presidencial chegará amanhã, às 7h, ao aeroporto de Brasília."}'::jsonb,'E',false,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno'),
('FGV','Assembleia Legislativa do Estado do Maranhão','Assistente Legislativo – Agente Legislativo',2023,null,'Tipo 1',60,'Redação Oficial',null,'“Apurado, com impressionante agilidade e precisão, naquela tarde de 2009, o resultado da consulta à população acreana, verificou- se que a esmagadora e ampla maioria da população daquele distante estado manifestou-se pela efusiva e indubitável rejeição da alteração realizada pela Lei nº 11.662/2008. Não satisfeita, inconformada e indignada, com a nova hora legal vinculada ao terceiro fuso, a maioria da população do Acre demonstrou que a ela seria melhor regressar ao quarto fuso, estando cinco horas a menos que em Greenwich”. O período acima foi incluído no Manual de Redação da Presidência da República como exemplo de um problema redacional que deve ser evitado, que é','{"A": "a não observância das regras da norma culta.", "B": "a inadequação no emprego de sinais gráficos.", "C": "a prolixidade, ou seja, o exagero desnecessário de palavras.", "D": "a seleção erudita, excessivamente culta, de vocábulos.", "E": "o desrespeito no emprego de letras maiúsculas."}'::jsonb,'C',true,true,'MA','Legislativo','https://conhecimento.fgv.br/sites/default/files/concursos/cnm202-assistente-legislativo-administrativo-agente-legislativocnm202-tipo-1.pdf','https://conhecimento.fgv.br/sites/default/files/concursos/alema-2023-gabarito-final-para-publicacao-retificado-04.10.2023.pdf','depende de figura, tabela ou gráfico do caderno original: conferir antes de ativar; conferir vigência da norma antes de ativar; disciplina atribuída pela ordem do caderno')
